function mostClasses(classes: number[][]): number {
  const n = classes.length;
  const sorted = [...classes].sort((a, b) => a[1] - b[1]);
  let best = 0;
  for (let mask = 0; mask < 1 << n; mask++) {
    let day = 0, count = 0, ok = true;
    for (let i = 0; i < n && ok; i++) {
      if (!(mask & (1 << i))) continue;
      day += sorted[i][0];
      count++;
      if (day > sorted[i][1]) ok = false;
    }
    if (ok) best = Math.max(best, count);
  }
  return best;
}

